"""Fly web vs worker process mode (Phase B load separation)."""

from __future__ import annotations

import os


def get_run_mode() -> str:
    return os.environ.get("RUN_MODE", "web").strip().lower()


def is_worker_mode() -> bool:
    return get_run_mode() == "worker"


def _background_flag() -> str:
    if is_worker_mode():
        return "off"
    return os.environ.get("BACKGROUND_ON_WEB", "on").strip().lower()


def background_on_web() -> bool:
    """True when web should run any background schedulers (essential or full)."""
    return _background_flag() not in ("0", "false", "no", "off")


def background_heavy_on_web() -> bool:
    """True for legacy combined mode — live subnets + feed warmup on web."""
    flag = _background_flag()
    return flag in ("1", "true", "yes", "on", "full")


def inline_worker_expected() -> bool:
    """True when web machine should host a sibling worker process (Fly v1)."""
    if split_worker_v2_enabled():
        return False
    return os.environ.get("INLINE_WORKER", "").strip().lower() in ("1", "true", "yes", "on")


def split_worker_v2_enabled() -> bool:
    """True when a dedicated Fly worker process group owns background jobs (v2)."""
    return os.environ.get("WORKER_SPLIT_V2", "").strip().lower() in ("1", "true", "yes", "on")


def stage2_hop_mode() -> bool:
    """Stage 2 temp worker — flycast hop proof only; skips background schedulers."""
    return os.environ.get("STAGE2_HOP", "").strip().lower() in ("1", "true", "yes", "on")


def worker_mode_label() -> str:
    """web | worker | split | combined — for /api/ops/readiness."""
    if is_worker_mode():
        return "worker"
    if split_worker_v2_enabled():
        return "split_v2"
    if inline_worker_expected():
        return "split"
    if background_on_web():
        return "combined"
    return "web"


def background_boot_allowed() -> bool:
    """Skip lifespan/worker boot under pytest or Deploy Guard."""
    if os.environ.get("PYTEST_CURRENT_TEST"):
        return False
    flag = os.environ.get("DISABLE_BACKGROUND_SCANS", "").strip().lower()
    return flag not in ("1", "true", "yes", "on")


def worker_heavy_feeds_enabled() -> bool:
    """True when full-universe feed warmup jobs run (WORKER_HEAVY=full only; not sync ownership)."""
    flag = os.environ.get("WORKER_HEAVY", "essential").strip().lower()
    return flag in ("1", "true", "yes", "on", "full")


def live_subnets_sync_owner_enabled() -> bool:
    """Worker owns live_subnets sync on prod split VMs; web is read-only unless combined."""
    if is_worker_mode():
        flag = os.environ.get("WORKER_HEAVY", "essential").strip().lower()
        return flag not in ("0", "false", "no", "off")
    return background_heavy_on_web()


def score_snapshot_producer_enabled() -> bool:
    """Exactly one process per volume owns score_snapshots.json production."""
    if stage2_hop_mode():
        return False
    if is_worker_mode():
        flag = os.environ.get("WORKER_HEAVY", "essential").strip().lower()
        return flag not in ("0", "false", "no", "off")
    return (
        background_heavy_on_web()
        and not inline_worker_expected()
        and not split_worker_v2_enabled()
    )
